  'tix.offline_limits': 'ஆஃப்லைனில் ஸ்கேன் அந்தச் சேமித்த பட்டியலுடன் மட்டுமே சரிபார்க்கப்படும்: அதன் பின் விற்ற, ரத்தான அல்லது மாற்றப்பட்ட டிக்கெட்டுகள் தெரியாது; ஆஃப்லைனில் உள்ள மற்றொரு வாயில் நீங்கள் அனுப்பும் வரை உங்கள் ஸ்கேன்களைப் பார்க்க முடியாது.',
