  "pay.upi.send": "கோரிக்கை அனுப்பு",
  "pay.upi.back": "பின்",
  "pay.upi.scan": "எந்த UPI செயலியிலும் ஸ்கேன் செய்யவும், அல்லது உங்கள் UPI செயலியைத் திறக்கவும்.",
  "pay.upi.waiting": "உங்கள் UPI செயலியில் கோரிக்கையை ஏற்று, பிறகு சரிபார்க்கவும்.",
  "pay.upi.autopay": "UPI AutoPay அமைக்கவும்",
  "pay.upi.autopay_note": "AutoPay ஒவ்வொரு காலத்திலும் தானாகவே கட்டணம் வசூலிக்கும். எப்போது வேண்டுமானாலும் நிறுத்தலாம்.",
  "pay.upi.autopay_done": "உங்கள் UPI செயலியில் AutoPay ஐ ஏற்று, திரும்பி வாருங்கள்.",
  "paykeys.title": "கட்டண வழங்குநர் விசைகள்",
  "paykeys.intro": "விசைகள் குறியாக்கம் செய்யப்படுகின்றன; மாற்றலாம் அல்லது நீக்கலாம், மீண்டும் படிக்க முடியாது. இங்கே அமைத்த விசை சர்வர் அமைப்பை மீறும்.",
  "paykeys.ready": "தயார்",
  "paykeys.not_ready": "அமைக்கவில்லை",
