  'dp.none': 'இன்னும் மேம்பாட்டுத் திட்டங்கள் இல்லை',
  'dp.none_sub': 'சேர்ந்த வீரருக்கு ஒரு திட்டத்தைத் திறக்கவும்: பருவம், பொறுப்புள்ள தலைவர், ஒவ்வொரு துறைக்கான இலக்குகளைத் தேர்ந்தெடுக்கவும்.',
  'dp.none_sub_coach': 'உங்கள் குழுக்களில் உள்ள வீரருக்கு ஒரு திட்டத்தைத் திறக்கவும். நீங்கள் அதன் தலைவராகி மற்ற நிபுணர்களை அழைக்கலாம்.',
