  'pk.g_title': '{name}: அழைத்துச் செல்லுதல் & பாதுகாப்பு',
  'pk.g_intro': 'பயிற்சியாளர்கள் இளம் வீரரை சரிபார்க்கப்பட்ட பாதுகாவலரிடமோ, நீங்கள் இங்கே பட்டியலிட்டு வரையறுத்த வரம்புக்குள் உள்ளவரிடமோ, நீங்கள் அனுமதித்த புறப்பாட்டு முறையிலோ மட்டுமே ஒப்படைப்பார்கள். ஒவ்வொரு வருகையையும் உங்கள் தொலைபேசியில் உறுதிசெய்வீர்கள்.',
