  'guide.safety.why': 'யார் வந்தார்கள், யார் உங்கள் பொறுப்பில் இருக்கிறார்கள், ஒவ்வொரு இளம் வீரரையும் யார் வீட்டிற்கு அழைத்துச் சென்றார்கள் என்பதை அறியுங்கள். யார் அழைத்துச் செல்லலாம் என்பதை பாதுகாவலர்கள் தீர்மானிக்கிறார்கள், ஊழியர்கள் சரிபார்த்து ஒப்படைக்கிறார்கள், தாமதமான அல்லது வராத நிலைகள் நீங்கள் அமைத்த நேரப்படி உயர் மட்டத்திற்குத் தெரிவிக்கப்படும்.',
