  "guide.content.why": "உங்கள் அங்கீகரிக்கப்பட்ட பயிற்சி முறை, பாடத்திட்டங்கள், பயிற்சிகள் மற்றும் நுண்பாடங்களை உரிமம் பெற்ற தொகுப்பாக வழங்குங்கள்; இதனால் இணைந்த மற்றும் சுயேச்சை நிறுவனங்கள் தங்கள் பயிற்சியாளர்களுக்கு இடங்களை வாங்க முடியும், அதேசமயம் உரிமைகள், பதிப்புகள் மற்றும் வருவாய்ப் பதிவு உங்களிடமே இருக்கும்.",
  "cl.sess.title": "உரிமம் பெற்ற உள்ளடக்கம்",
  "cl.sess.help": "உங்கள் அமைப்பு உரிமம் பெற்றுள்ள தொகுப்புகளின் உருப்படிகள், இந்தப் பயிற்சி அமர்வில் பயன்படுத்தப்படுகின்றன. ஒரு உருப்படியை இணைத்து, பின்னர் உங்கள் சொந்தத் திட்டத்தில் சேர்க்கவும்.",
  "cl.sess.add": "உரிமம் பெற்ற உள்ளடக்கத்தைச் சேர்",
  "cl.sess.pick": "நீங்கள் பயன்படுத்தக்கூடிய உருப்படிகள்",
  "cl.sess.added": "இந்த அமர்வில் சேர்க்கப்பட்டது",
  "cl.sess.empty": "உரிமம் பெற்ற உள்ளடக்கம் எதுவும் இணைக்கப்படவில்லை",
  "cl.sess.empty_pick": "உங்கள் அமைப்பு உரிமம் பெற்றுள்ள தொகுப்பிலிருந்து ஒரு பயிற்சி, பாடத்திட்டம் அல்லது சிறு படிப்பை இணைக்கவும்.",
  "cl.sess.empty_none": "உங்களுக்கு இடம் (seat) உள்ள உரிமம் பெற்ற உள்ளடக்கம் உங்கள் அமைப்பில் இன்னும் இல்லை. உள்ளடக்கம் பிரிவில் சந்தையைப் பாருங்கள்.",
  "cl.sess.withdrawn": "திரும்பப் பெறப்பட்டது",
  "cl.sess.locked_hint": "இந்த உரிமம் செயலில் இல்லை, எனவே உள்ளடக்கம் பூட்டப்பட்டுள்ளது. புதுப்பிக்க உங்கள் அகாடமி நிர்வாகியிடம் கேளுங்கள். ஏற்கனவே உருவாக்கிய திட்டத் தொகுதிகள் உங்கள் பதிவில் இருக்கும்.",
  "cl.sess.no_seat": "இந்தத் தொகுப்புக்கு உங்களுக்கு இடம் (seat) இல்லை.",
  "cl.sess.unlink": "இணைப்பை நீக்கு",
  "cl.sess.unlinked": "இந்த அமர்விலிருந்து இணைப்பு நீக்கப்பட்டது",
  "cl.sess.load": "என் திட்டத்தில் சேர்",
  "cl.sess.load_hint": "பயிற்சிகள், இலக்குகள் மற்றும் சிறு படிப்புகளை உங்கள் சொந்தப் பயிற்சித் திட்டத்தில் தொகுதிகளாகச் சேர்க்கும். உரிமம் ஆஃப்லைன் நகல்களை அனுமதித்தால் உரை தொகுதியில் நகலெடுக்கப்படும்; இல்லையெனில் தொகுதி உரிமம் பெற்ற உருப்படியுடன் இணைக்கப்படும்.",
  "cl.sess.loaded": "உங்கள் திட்டத்தில் {n} தொகுதிகள் சேர்க்கப்பட்டன",
  "cl.sess.loaded_done": "திட்டம் புதுப்பிக்கப்பட்டது",
  "cl.sess.nothing_new": "அனைத்தும் ஏற்கனவே உங்கள் திட்டத்தில் உள்ளன",
  "cl.sess.licensed_tag": "உரிமம் பெற்றது",
  'cap.title': 'திறனும் பணியாளர்களும்',
  'cap.intro': 'உங்கள் உண்மையான அமர்வுகள், ஊதியம், முன்பதிவுகள், வளர்ச்சிப் பாதைகளின் அடிப்படையில் சேர்க்கை, பதவி உயர்வு, புதிய குழு, இடம், பயிற்சியாளர்கள் பற்றி “என்ன ஆகும்” என்று சோதிக்கவும். உங்கள் அகாடமியில் எதுவும் மாறாது.',
