  'guide.wellbeing.title': 'மாணவரின் நலன் மற்றும் வளர்ச்சிக்கு ஆதரவளியுங்கள்',
  'guide.wellbeing.why': 'குடும்பத்தின் சம்மதத்துடன் வழிகாட்டல், சந்திப்புகள், வளர்ச்சி இலக்குகள், விருப்பத் தடங்கள் வழங்குங்கள்; என்ன பேசப்பட்டது என்பதைப் பார்க்காமல் என்ன நிலுவையில் உள்ளது என்பதைக் காணுங்கள்.',
'pk.r_too_many': 'கடவுச்சொற்றொடர் பலமுறை தவறாக இருந்தது. நிறுத்தி பாதுகாவலரை அழைக்கவும்.',

