  'arp.tab.schedules': 'அட்டவணைகள்',
  'arp.tab.issued': 'வழங்கப்பட்டவை',
  'arp.k.awaiting': 'மதிப்பாய்வுக்காக காத்திருப்பு',
  'arp.k.overdue': '{n} தாமதம்',
  'arp.k.issued': 'வழங்கப்பட்டவை, கடந்த 90 நாட்கள்',
  'arp.k.scheduled': 'திட்டமிடப்பட்டவை',
  'arp.k.next': 'அடுத்தது {date}',
  'arp.k.revoked': 'திரும்பப் பெறப்பட்டவை',
  'arp.k.history_kept': 'வரலாறு பாதுகாக்கப்படும்',
  'arp.kind.progress': 'மேம்பாடு & மதிப்பீட்டு அறிக்கை',
  'arp.kind.term': 'பருவ அறிக்கை',
  'arp.kind.management': 'வாரிய மேலாண்மை தொகுப்பு',
  'arp.kind.finance': 'இலாப நட்ட தொகுப்பு',
  'arp.kind.campus': 'வளாக தரத் தொகுப்பு',
  'arp.scope.athlete': 'வீரர்',
  'arp.scope.campus': 'வளாகம்',
  'arp.scope.academy': 'அகாடமி',
  'arp.aud.progress': 'அகாடமி உரிமையாளர்கள், நிர்வாகிகள், வீரரின் பயிற்சியாளர், வீரர் மற்றும் சரிபார்க்கப்பட்ட பாதுகாவலர் படிக்கலாம். நிதி, மருத்துவ அல்லது நலக் குறிப்புகள், பயிற்சியாளர் மற்றும் ஊழியரின் தனிப்பட்ட கருத்துகள் ஒருபோதும் சேர்க்கப்படாது.',
  'arp.aud.term': 'வளர்ச்சி அறிக்கையின் அதே வாசகர்கள். பருவ வருகையையும், பகிரப்பட்டிருந்தால் பள்ளி நிலையையும் சேர்க்கிறது. பள்ளி மதிப்பெண்கள் ஒருபோதும் அச்சிடப்படாது.',
  'arp.aud.management': 'அகாடமி உரிமையாளர்கள், நிர்வாகிகள் மட்டுமே படிக்கலாம். 3-க்கும் குறைவான குழுக்கள் எண்ணாக அச்சிடப்படாது. சட்ட, மருத்துவ அல்லது பயிற்சியாளரின் தனிப்பட்ட விவரங்கள் இல்லை.',
  'arp.aud.finance': 'அகாடமி உரிமையாளர்கள், நிர்வாகிகள், நிதிப் பிரிவு மட்டுமே படிக்கலாம். நிர்வாகக் கணக்குகள்; சட்டப்படியான அல்லது தணிக்கை செய்யப்பட்ட கணக்குகள் அல்ல. பயிற்சி அல்லது மருத்துவ தரவு இல்லை.',
  'arp.aud.campus': 'அகாடமி உரிமையாளர்கள், நிர்வாகிகள் மட்டுமே படிக்கலாம். ஒரு வளாகம்: ஆட்கள், செயல்பாடு, ஊழியர், நிதி. 3-க்கும் குறைவான குழுக்கள் எண்ணாக அச்சிடப்படாது.',
  'arp.basis.progress': 'வீரருக்குப் பாதுகாப்பான முன்னேற்றக் காட்சி: பயிற்சியாளர் மதிப்பீடுகள், அகாடமி வருகை, அங்கீகரிக்கப்பட்ட அதிகாரப்பூர்வ முடிவுகள் தனித்தனியாக.',
  'arp.basis.term': 'பருவத்துக்கான முன்னேற்றக் காட்சி, பருவ வருகை, பகிரப்பட்டிருந்தால் பள்ளி நிலை. எதுவும் ஒரே மதிப்பெண்ணாக இணைக்கப்படாது.',
  'arp.basis.management': 'நிர்வாகத் தலைமை முகப்பின் அதே புள்ளிவிவரங்களிலிருந்து நிர்வாகக் காட்சி. சட்டப்படியான கணக்குகள் அல்ல.',
  'arp.basis.finance': 'நிதி பேரேடு, அங்கீகரிக்கப்பட்ட சம்பளப் பட்டியல், உறுதிசெய்யப்பட்ட மைதான முன்பதிவுகளிலிருந்து நிர்வாகக் கணக்குகள். சட்டப்படியானது அல்லது தணிக்கை செய்யப்பட்டது அல்ல.',
  'arp.basis.campus': 'ஒரு வளாகத்தின் நிர்வாகக் காட்சி, நிர்வாக முகப்பு மற்றும் இலாப நட்டத்தின் அதே புள்ளிவிவரங்களிலிருந்து.',
