  'acc.by_reference': 'சான்றுகள் ஏற்கனவே இருக்கும் இடத்திலிருந்தே இணைக்கப்படுகின்றன: பயிற்சியாளர் தகுதிச் சான்றுகள், இணக்கப் பதிவுகள். எதுவும் நகலெடுக்கப்படுவதில்லை; செல்லுபடியாகும் நிலை நேரடியாகப் படிக்கப்படும்.',
