  'acc.mine_sub': 'நீங்கள் ஆய்வாளராகக் குறிப்பிடப்பட்டுள்ள தணிக்கைகள்',
  'acc.mine_card_sub': 'ஆய்வாளராக உங்களுக்கு {n} தணிக்கைகள் ஒதுக்கப்பட்டுள்ளன',
  'acc.mine_empty_title': 'தணிக்கைகள் ஒதுக்கப்படவில்லை',
  'acc.mine_empty_sub': 'ஒரு அகாடமி உங்களை ஆய்வாளராகக் குறிப்பிடும்போது, தணிக்கை இங்கே தோன்றும்.',
  'guide.accreditation.title': 'அங்கீகாரத்தையும் தணிக்கைகளையும் நிர்வகிக்கவும்',
  'guide.accreditation.why': 'உங்கள் அகாடமி பெற்றுள்ள ஒவ்வொரு வெளி அங்கீகாரம், உரிமம், தரக் குறியீட்டையும் கண்காணியுங்கள்; ஒவ்வொன்றின் சான்றுகளையும் நீங்கள் ஏற்கனவே பராமரிக்கும் பதிவுகளுடன் இணைத்து வையுங்கள்; கண்டறிதல்கள், திருத்த நடவடிக்கைகளுடன் தணிக்கைகளை நடத்துங்கள் - அவற்றை யாரும் மறைமுகமாக மாற்ற முடியாது.',
  'guide.accreditation.s1': 'அகாடமி, பின்னர் அங்கீகாரம் என்பதைத் திறந்து, அமை என்பதைத் தட்டி கட்டமைப்பைச் சேர்க்கவும்: அங்கீகரிக்கும் அமைப்பு, வகை, நிலை, பொறுப்பாளர், புதுப்பிப்பு சுழற்சி, நினைவூட்டல் முன்கூட்டிய காலம்.',
  'guide.accreditation.s2': 'கட்டமைப்பைத் திறந்து, சான்றுகள் என்பதைத் தேர்ந்தெடுத்து, அதற்குத் தேவையானவற்றைச் சேர்த்து, பயிற்சியாளர் தகுதிச் சான்றுகளையும் இணக்கப் பதிவுகளையும் இணைக்கவும். எதுவும் நகலெடுக்கப்படாது; செல்லுபடியாகும் நிலை நேரடியாகப் படிக்கப்படும்.',
  'guide.accreditation.s3': 'தணிக்கையைத் திட்டமிடு என்பதைத் தட்டி, வகை, தேதி, சரிபார்க்க வேண்டிய பகுதிகளைத் தேர்ந்தெடுக்கவும்; விருப்பமாக ஒரு ஆய்வாளரைக் குறிப்பிடலாம், அவர் அந்தத் தணிக்கையை மட்டுமே பார்ப்பார்.',
  'guide.accreditation.s4': 'ஒவ்வொரு கண்டறிதலையும் அதன் தீவிரத்துடனும் திருத்த நடவடிக்கைகளுடனும் பதிவு செய்து, ஒவ்வொரு நடவடிக்கைக்கும் பொறுப்பாளரையும் காலக்கெடுவையும் வழங்கி, பணி முடிந்ததும் முடிந்தது எனக் குறிக்கவும்.',
  'guide.accreditation.s5': 'அதிக மற்றும் நடுத்தரக் கண்டறிதல்கள் அனைத்தும் தீர்க்கப்பட்டதும் மீண்டும் சமர்ப்பித்து, ஆய்வாளர் முடிவைப் பதிவு செய்யவும். ஒவ்வொரு படியும் பூட்டப்பட்ட பதிவுத்தடத்தில் வைக்கப்படும்.',
