  'inc.a_none_sub': 'முதலில் ஒரு பாதை நிலைக்கு மதிப்பீட்டைப் பதிவு செய்யுங்கள்; பின்னர் இங்கே அதைத் தழுவலாக மாற்றுங்கள்.',
  'inc.a_title': 'பயிற்சியாளர் வழிநடத்தும் தழுவிய மதிப்பீடு',
  'inc.a_note': 'ஒவ்வொரு பரிமாணத்தையும் சொற்களில் விவரியுங்கள். எண்ணோ ஒற்றை மதிப்பெண்ணோ இல்லை.',
