  'inc.a_sign': 'இரண்டாம் மதிப்பீட்டாளராக ஒப்புதல் அளி',
  'inc.a_sign_a11y': 'இந்தத் தழுவிய மதிப்பீட்டிற்கு இரண்டாம் மதிப்பீட்டாளராக ஒப்புதல் அளி',
