  'inc.a_saved': 'தழுவிய மதிப்பீடு சேமிக்கப்பட்டது',
  'inc.a_signed': 'ஒப்புதல் அளிக்கப்பட்டது',
  'inc.lvl_emerging': 'தொடக்க நிலை',
  'inc.lvl_developing': 'வளர்ந்து வரும் நிலை',
  'inc.lvl_secure': 'உறுதியான நிலை',
  'inc.lvl_exceeding': 'எதிர்பார்ப்பை மிஞ்சிய நிலை',
  'guide.inclusion.title': 'உள்ளடக்கிய, தழுவல் திட்டங்களை நடத்துங்கள்',
  'guide.inclusion.why': 'மாற்றுத்திறனாளி மற்றும் பாரா விளையாட்டு வீரர்கள் நோய் அறிதலை வெளிப்படுத்தாமலேயே உங்கள் திட்டங்களில் சேர்ந்து முன்னேற வழிசெய்யுங்கள்: திட்டம் வழங்குவதை அமைக்கவும், ஒவ்வொரு தழுவல் அமர்வும் தயாராக உள்ளதா எனச் சரிபார்க்கவும், வீரர்கள் தாங்கள் தேர்ந்தெடுக்கும் செயல்பாட்டுத் தேவைகளை மட்டும் பகிரட்டும்.',
  'guide.inclusion.s1': 'அகாடமி, பின்னர் உள்ளடக்கம், பின்னர் திட்ட அமைப்பு என்பதைத் திறந்து, ஒரு திட்டத்தைத் தேர்ந்தெடுத்து யார் சேரலாம், விளையாட்டுத் தழுவல் வார்ப்புருக்கள், வழங்கப்படும் மாற்றங்கள், இடத்தின் வசதிகள், தேவையான துணையாளர் விகிதம் ஆகியவற்றைத் தேர்ந்தெடுக்கவும்.',
  'guide.inclusion.s2': 'ஒவ்வொரு இடத்தின் அணுகல் வசதிகளையும் (லிஃப்ட், படிகள் இல்லாத வழி, அணுகக்கூடிய உடை மாற்றும் அறை, குளத்தில் தூக்கும் கருவி) பதிவு செய்யுமாறு இட மேலாளர்களிடம் கேளுங்கள்; அப்போது அமர்வுகளை அவற்றுடன் சரிபார்க்கலாம்.',
  'guide.inclusion.s3': 'வீரர்கள், அல்லது இளையவரின் சரிபார்க்கப்பட்ட பாதுகாவலர், எனது அகாடமி, பின்னர் தங்குமிட ஏற்பாடுகள் என்பதைத் திறந்து, பணியாளர்களுக்குத் தேவையானதை மட்டும், யாருடன், எதுவரை என்பதைத் தேர்ந்து பகிர்கிறார்கள். எந்த நேரத்திலும் அதைத் திரும்பப் பெறலாம்.',
  'guide.inclusion.s4': 'உள்ளடக்கம், பின்னர் அமர்வு தயார்நிலை என்பதைத் திறந்து, ஓர் அமர்வைத் தேர்ந்தெடுத்து ஒவ்வொரு குறையையும் தீர்க்கவும்: இடம், துணையாளர்கள், பணிப் பொறுப்பு மற்றும் தலைமைப் பயிற்சியாளர் தகுதிச் சான்று. பயிற்சியாளர்களும் இடப் பணியாளர்களும் தங்களுடன் பகிரப்பட்டதை மட்டுமே காண்பார்கள்; ஒவ்வொரு பார்வையும் வீரருக்காகப் பதிவு செய்யப்படும்.',
  'guide.inclusion.s5': 'விளக்க நிலைகளுடன், பயிற்சியாளர் வழிநடத்தும் தழுவிய மதிப்பீடுகளைப் பதிவு செய்யுங்கள்; ஒற்றை மதிப்பெண் வேண்டாம்; இரண்டாம் மதிப்பீட்டாளர் ஒப்புதல் அளிக்கட்டும். இயக்குநர்கள் மேலோட்டப் பக்கத்தில் எண்ணிக்கைகளை மட்டுமே காண்பார்கள்.',

